   "code": "// Fit documents into a context budget, best first, leaving room for the answer\nconst tokens = s => Math.ceil(s.length / 4);              // rough rule for English\nfunction buildContext({ system, history, docs, question, window = 16_000, reserveOutput = 2_000 }) {\n  let budget = window - reserveOutput - tokens(system) - tokens(question);\n  const keptHistory = [];\n  for (const turn of [...history].reverse()) { const t = tokens(turn); if (t > budget * 0.3) break; keptHistory.unshift(turn); budget -= t; }\n  const keptDocs = [];\n  for (const d of [...docs].sort((a, b) => b.score - a.score)) { const t = tokens(d.text); if (t <= budget) { keptDocs.push(d.id); budget -= t; } }\n  return { keptHistory: keptHistory.length, keptDocs, tokensLeft: budget };\n}\nconst docs = [\n  { id: 'refund-policy', score: 0.91, text: 'x'.repeat(24_000) },\n  { id: 'shipping', score: 0.55, text: 'x'.repeat(20_000) },\n  { id: 'faq', score: 0.72, text: 'x'.repeat(16_000) },\n];\nconst history = Array.from({ length: 12 }, () => 'y'.repeat(1_200));\nconsole.log(buildContext({ system: 'z'.repeat(6_000), history, docs, question: 'Can I get a refund after 40 days?' }));",
