   "code": "// An agent loop with a step limit, a tool allowlist and an approval gate\nconst tools = {\n  search_orders: { write: false, run: ({ email }) => [{ id: 'A17', status: 'delivered', total: 59 }] },\n  refund_order:  { write: true,  run: ({ id }) => ({ refunded: id }) },\n};\n// A scripted stand-in for the model, so the loop is runnable\nconst script = [\n  { tool: 'search_orders', args: { email: 'kim@example.com' } },\n  { tool: 'refund_order', args: { id: 'A17' } },\n  { done: 'Refund for order A17 has been issued.' },\n];\nasync function runAgent({ maxSteps = 5, approve }) {\n  const log = [];\n  for (let step = 0; step < maxSteps; step++) {\n    const action = script[step];\n    if (action.done) { log.push(`final: ${action.done}`); return log; }\n    const tool = tools[action.tool];\n    if (!tool) { log.push(`blocked unknown tool ${action.tool}`); continue; }\n    if (tool.write && !(await approve(action))) { log.push(`denied ${action.tool}`); return log; }\n    log.push(`${action.tool} -> ${JSON.stringify(tool.run(action.args))}`);\n  }\n  log.push('stopped: step limit'); return log;\n}\nrunAgent({ approve: async a => { console.log('approval requested for', a.tool, a.args); return true; } }).then(l => console.log(l.join('\\n')));",
